/* syscalls.c
 * Newlib syscall stubs: route printf() to USART2 (PA2=TX, PA3=RX).
 *
 * Target: STM32F405 (QEMU netduinoplus2 / real HW).
 * HSI 16 MHz, 115200 baud, 8N1.
 *
 * Generated by StaTable Eclipse Installer v0.1.0
 * Adjust RCC / GPIO / USART addresses for your MCU.
 */
#include <stdint.h>
#include <errno.h>
#include <sys/stat.h>

/* --- RCC (0x40023800) --- */
#define RCC_BASE        0x40023800UL
#define RCC_AHB1ENR     (*(volatile uint32_t *)(RCC_BASE + 0x30UL))
#define RCC_APB1ENR     (*(volatile uint32_t *)(RCC_BASE + 0x40UL))

/* --- GPIOA (0x40020000) --- */
#define GPIOA_BASE      0x40020000UL
#define GPIOA_MODER     (*(volatile uint32_t *)(GPIOA_BASE + 0x00UL))
#define GPIOA_AFRL      (*(volatile uint32_t *)(GPIOA_BASE + 0x20UL))
#define GPIOA_AFRH      (*(volatile uint32_t *)(GPIOA_BASE + 0x24UL))

/* --- USART1 (0x40011000) --- */
#define USART1_BASE     0x40011000UL
#define USART1_SR       (*(volatile uint32_t *)(USART1_BASE + 0x00UL))
#define USART1_DR       (*(volatile uint32_t *)(USART1_BASE + 0x04UL))
#define USART1_BRR      (*(volatile uint32_t *)(USART1_BASE + 0x08UL))
#define USART1_CR1      (*(volatile uint32_t *)(USART1_BASE + 0x0CUL))
#define RCC_APB2ENR     (*(volatile uint32_t *)(RCC_BASE + 0x44UL))

#define USART_SR_TXE    (1U << 7)
#define USART_CR1_UE    (1U << 13)
#define USART_CR1_TE    (1U << 3)
#define USART_CR1_RE    (1U << 2)

void uart2_init(void)
{
    RCC_AHB1ENR |= (1U << 0);    /* GPIOAEN */
    RCC_APB2ENR |= (1U << 4);    /* USART1EN */

    /* PA9 = AF7 (USART1_TX), PA10 = AF7 (USART1_RX) */
    GPIOA_MODER &= ~((3U << 18) | (3U << 20));
    GPIOA_MODER |=  ((2U << 18) | (2U << 20));
    GPIOA_AFRH  &= ~((0xFU << 4) | (0xFU << 8));
    GPIOA_AFRH  |=  ((7U << 4) | (7U << 8));

    USART1_BRR = 16000000UL / 115200UL;  /* ~139 */
    USART1_CR1 = USART_CR1_UE | USART_CR1_TE | USART_CR1_RE;
}

void uart2_putc(char c)
{
    while (!(USART1_SR & USART_SR_TXE)) { }
    USART1_DR = (uint32_t)(unsigned char)c;
}

/* --- Newlib stubs --- */
int _write(int fd, char *buf, int len)
{
    (void)fd;
    for (int i = 0; i < len; i++) {
        uart2_putc(buf[i]);
    }
    return len;
}

int _read(int fd, char *buf, int len)
{
    (void)fd; (void)buf; (void)len;
    return 0;
}

int _close(int fd) { (void)fd; return -1; }

int _fstat(int fd, struct stat *st)
{
    (void)fd;
    st->st_mode = S_IFCHR;
    return 0;
}

int _isatty(int fd) { (void)fd; return 1; }

int _lseek(int fd, int ptr, int dir)
{
    (void)fd; (void)ptr; (void)dir;
    return 0;
}

int _getpid(void) { return 1; }

int _kill(int pid, int sig)
{
    (void)pid; (void)sig;
    errno = EINVAL;
    return -1;
}


/* --- Heap management (required by newlib) --- */
extern char _ebss;

void *_sbrk(int incr)
{
    static char *heap_end = 0;
    char *prev;
    if (heap_end == 0) {
        heap_end = &_ebss;
    }
    prev = heap_end;
    heap_end += incr;
    return prev;
}

void _exit(int status)
{
    (void)status;
    for (;;) { }
}
